                    $this->createEventManager($services->get('SharedEventManager')),
                'SharedEventManager'      => static fn($services, $name): SharedEventManager =>
                new SharedEventManager(),
            ],
            'shared'    => [
                'EventManager' => false,
            ],
        ])

